<script setup lang="ts">
import { ref,computed,onMounted,onBeforeUnmount,watch,defineAsyncComponent } from 'vue'
import { get,post } from '@/api/client'
import MonitorChart from '@/components/MonitorChart.vue'
import DaylightMap from '@/components/DaylightMap.vue'
import { associatedModels, earthImpact, earthArrival, type SolarEvent, type PropagationModel } from '@/components/space/impact'
const SolarPropagation3D=defineAsyncComponent(()=>import('@/components/space/SolarPropagation3D.vue'))
const propagationView=ref<'3d'|'2d'>('3d')
type Source={id:string;name:string;url:string;kind:string;status:string;error?:string;success?:number}
type Observation={id:string;instrument:string;observed_at:string|null;fetched_at:string;time_note:string;source_url:string}
type Frame={id:string;run:string;valid:number}
type Event=SolarEvent
type Simulation=PropagationModel
type Summary={now:string;enabled:boolean;sources:Source[];observations:Observation[];forecast:{text:string;issued_at?:string;valid_until?:string;days?:{date:string;kp_max:number|null;r1_r2:number|null;r3_plus:number|null;s1_plus:number|null}[]}|null;alerts:{product_id:string;title?:string;issue_datetime:string;message:string;status:string;valid_from?:string;valid_until?:string;communication_related?:boolean}[];events:Event[];simulations:Simulation[]}
type Point={t:number;v:number;seen:number;kind:string}
const data=ref<Summary|null>(null),error=ref(''),busy=ref(false),clock=ref(Date.now()/1000),useUTC=ref(false)
const mode=ref('live'),history=ref(''),cursor=ref<number>(),run=ref(''),compareRun=ref(''),frames=ref<Frame[]>([]),compareFrames=ref<Frame[]>([]),runs=ref<{run:string;frames:number}[]>([])
const index=ref(0),playing=ref(false),speed=ref(1),imageFailed=ref(false),selected=ref<Event|null>(null),sourceOpen=ref(false),imageOpen=ref<Observation|null>(null)
const jobs=ref<{id:string;state:string;created:number;updated:number;payload:string}[]>([])
const series=ref<Record<string,{points:Point[];unit:string}>>({})
const range=ref(24),showAlerts=ref(false),communicationOnly=ref(false),eventSearch=ref('')
const shownEvents=computed(()=>(data.value?.events||[]).filter(e=>JSON.stringify(e).toLowerCase().includes(eventSearch.value.toLowerCase())).sort((a,b)=>b.startTime.localeCompare(a.startTime)))
const shownAlerts=computed(()=>(data.value?.alerts||[]).filter(a=>!communicationOnly.value||a.communication_related))
let refresh:ReturnType<typeof setInterval>|undefined,play:ReturnType<typeof setInterval>|undefined,clockTimer:ReturnType<typeof setInterval>|undefined,generation=0,framesGeneration=0
const metrics=['speed','density','bt','bz','kp','kp_forecast','xray','protons']
const asset=(id:string)=>'/api/sw/assets?id='+encodeURIComponent(id)
const fmt=(v:string|number|null|undefined)=>v?new Date(typeof v==='number'?v*1000:v).toLocaleString('zh-CN',{timeZone:useUTC.value?'UTC':'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未知'
const frameReady=ref(false)
const current=computed(()=>frames.value[index.value])
const comparison=computed(()=>compareFrames.value.find(f=>f.valid===current.value?.valid))
const latestPoint=(metric:string)=>series.value[metric]?.points.filter(p=>p.t<=clock.value).slice(-1)[0]
const oldPoint=(metric:string)=>!latestPoint(metric)||clock.value-latestPoint(metric)!.t>(metric==='kp'?21600:900)
const latest=(metric:string)=>{const points=series.value[metric]?.points.filter(p=>p.t<=clock.value)||[];return points.length?points[points.length-1]!.v.toPrecision(3):'—'}
// The monitor stays usable if the independent training summary cannot be read.
// Unknown training state keeps rendering conservative until the next check.
const trainingActive=ref(true)
async function loadTrainingActivity(){
  try{
    const result=await get<{runs:{state:string}[];progress?:{automatic_continuation?:boolean}}>('/training/summary')
    trainingActive.value=!!result.progress?.automatic_continuation||result.runs.some(r=>r.state==='running'||r.state==='needs_verification')
  }catch{trainingActive.value=true}
}
const selectedSimulations=computed(()=>associatedModels(selected.value,data.value?.simulations||[]))
const selectedImpact=computed(()=>earthImpact(selected.value,data.value?.simulations||[],clock.value))
function arrival(s:Simulation){
  const at=earthArrival(s)
  return at?`${fmt(at)}${Date.parse(at)/1000<=clock.value?' · 待观测确认':''}`:'未给出地球到达估计'
}
async function load(){
  const n=++generation;error.value='';busy.value=true
  const cutoff=mode.value==='history'&&history.value?new Date(history.value).toISOString():undefined
  const end=cutoff||new Date().toISOString(),start=new Date(Date.parse(end)-range.value*3600000).toISOString()
  const results=await Promise.allSettled([get<Summary>('/sw/summary',{as_of:cutoff}),get<{runs:typeof runs.value}>('/sw/propagation/runs',{as_of:cutoff}),...metrics.map(metric=>get<{points:Point[];unit:string}>('/sw/series',{metric,start,end,as_of:cutoff})),get<{jobs:typeof jobs.value}>('/sw/jobs')])
  if(n!==generation)return
  const summary=results[0]!,runResult=results[1]!
  if(summary.status==='fulfilled'){data.value=summary.value as Summary;if(selected.value)selected.value=data.value.events.find(e=>e.activityID===selected.value!.activityID)||null}else error.value=String(summary.reason)
  if(runResult.status==='fulfilled'){runs.value=(runResult.value as {runs:typeof runs.value}).runs;if(!run.value&&runs.value.length){run.value=runs.value[0]!.run}}
  metrics.forEach((metric,i)=>{const result=results[i+2]!;if(result.status==='fulfilled')series.value[metric]=result.value as {points:Point[];unit:string}})
  const jobResult=results[results.length-1]!
  if(jobResult.status==='fulfilled')jobs.value=(jobResult.value as {jobs:typeof jobs.value}).jobs
  busy.value=false
}
async function loadFrames(){
  const n=++framesGeneration
  playing.value=false;frames.value=[];compareFrames.value=[];index.value=0;imageFailed.value=false
  if(!run.value)return
  const as_of=mode.value==='history'&&history.value?new Date(history.value).toISOString():undefined
  try{
    const [a,b]=await Promise.all([get<{frames:Frame[]}>('/sw/propagation/frames',{run:run.value,as_of}),compareRun.value?get<{frames:Frame[]}>('/sw/propagation/frames',{run:compareRun.value,as_of}):Promise.resolve({frames:[]})])
    if(n!==framesGeneration)return
    frames.value=a.frames;compareFrames.value=b.frames
    const nearest=a.frames.reduce((best,f,i)=>Math.abs(f.valid-clock.value)<Math.abs((a.frames[best]?.valid||0)-clock.value)?i:best,0)
    index.value=nearest
  }catch(e){if(n===framesGeneration)error.value=String(e)}
}
async function sync(id?:string){try{await post('/sw/sync',{source:id});error.value='更新任务已启动，完成后自动显示；关闭页面不取消采集。'}catch(e){error.value=String(e)}}
function step(delta:number){index.value=Math.max(0,Math.min(frames.value.length-1,index.value+delta));imageFailed.value=false}
async function pin(){try{const result=await post<{pinned_frames:number}>('/sw/pin',{run:run.value});error.value=`已固定 ${result.pinned_frames} 帧，缓存清理将保留此批次。`}catch(e){error.value=String(e)}}
function full(){void document.querySelector('.propagation')?.requestFullscreen()}
function pickTime(t:number){cursor.value=t;playing.value=false}
watch([run,compareRun],()=>void loadFrames())
watch(index,()=>{frameReady.value=false;imageFailed.value=false;cursor.value=current.value?.valid})
watch([mode,range],()=>{playing.value=false;selected.value=null;run.value='';void load()})
onMounted(()=>{void load();void loadTrainingActivity();refresh=setInterval(()=>{void loadTrainingActivity();if(mode.value==='live')void load()},60000);clockTimer=setInterval(()=>clock.value=Date.now()/1000,1000);play=setInterval(()=>{if(playing.value&&frameReady.value&&frames.value.length){if(index.value>=frames.value.length-1)playing.value=false;else step(1)}},1000)})
watch(speed,()=>{clearInterval(play);play=setInterval(()=>{if(playing.value&&frameReady.value&&frames.value.length){if(index.value>=frames.value.length-1)playing.value=false;else step(1)}},1000/speed.value)})
onBeforeUnmount(()=>{generation++;framesGeneration++;clearInterval(refresh);clearInterval(play);clearInterval(clockTimer)})
</script>

<template>
<div class="monitor">
  <header class="monitor-head"><strong>☀ MDVA 空间天气监测台</strong><nav><RouterLink to="/monitor">监测总览</RouterLink><RouterLink to="/solar">太阳科学工作台</RouterLink><RouterLink to="/console">数据与标注</RouterLink></nav><span>{{fmt(clock)}} {{useUTC?'UTC':'北京时间'}}</span><button @click="useUTC=!useUTC">切换时区</button><button @click="sourceOpen=!sourceOpen">信源健康 {{data?.sources.filter(s=>s.status==='ok').length||0}}/{{data?.sources.length||0}}</button></header>
  <div class="filters"><label>模式 <select v-model="mode"><option value="live">当前监测</option><option value="history">历史留存回放</option></select></label><template v-if="mode==='history'"><input v-model="history" type="datetime-local"/><button @click="run='';load()">载入当时已留存资料</button></template><label>曲线 <select v-model="range"><option :value="6">过去6小时</option><option :value="24">过去24小时</option><option :value="72">过去3天</option></select></label><span>关注：短波通信 · 观测、机构预报、研究模拟分别展示</span><button :disabled="!data?.enabled" @click="sync()">检查更新</button><span>{{busy?'读取中…':data?.enabled?'公开信源自动采集':'离线缓存模式'}}</span></div>
  <p v-if="error" class="notice" role="status">{{error}} <button @click="load">重试读取</button></p>
  <div v-if="sourceOpen" class="source-list"><div v-for="s in data?.sources" :key="s.id"><a :href="s.url" target="_blank" rel="noreferrer">{{s.name}}</a><b :class="s.status">{{s.status==='ok'?'最近检查成功':s.status==='stale'?'尚无更新/过期':'获取失败'}}</b><span>最近成功 {{fmt(s.success)}}</span><span>{{s.error}}</span><button @click="sync(s.id)">重试</button></div><details><summary>手动采集任务记录</summary><div v-for="job in jobs" :key="job.id">{{fmt(job.updated)}} · {{job.state}} · {{job.id}}<pre>{{job.payload}}</pre></div></details></div>
  <section class="telemetry"><div v-for="[metric,title,unit] in [['speed','太阳风速度','km/s'],['density','质子密度','cm⁻³'],['bt','IMF Bt','nT'],['bz','IMF Bz','nT'],['kp','Kp 观测',''],['xray','X射线','W/m²']]" :key="metric"><small>{{title}}</small><b>{{latest(metric!)}} <em>{{unit}}</em></b><small :class="{old:oldPoint(metric!)}">{{fmt(latestPoint(metric!)?.t)}} · {{oldPoint(metric!)?'缺测或过期':'观测'}}</small></div></section>
  <div class="main-grid">
    <section class="panel observations"><h2>太阳多通道观测 <small>NASA SDO</small></h2><div class="solar-grid"><button v-for="ob in data?.observations" :key="ob.id" @click="imageOpen=ob"><span>{{ob.instrument}}</span><img :src="asset(ob.id)" :alt="ob.instrument"/><small>{{ob.observed_at?'观测':'获取'}} {{fmt(ob.observed_at||ob.fetched_at)}}</small></button><div v-if="!data?.observations.length" class="empty">等待公开影像采集<br/>原始时间图注随影像保留</div></div><p>各通道独立观测，未自动配准。点击放大查看原始时间。</p><div class="unavailable"><b>Hα 观测说明</b><span>KSO 受地面天气影响，缩略图可跨日过期；AIA304 不替代 Hα，未用于模型推理。</span></div><div class="unavailable"><b>太阳识别 / 24h 耀斑预测</b><span>尚未训练验收 · 不显示虚构概率</span><RouterLink to="/solar">查看原始参考与基线依据 →</RouterLink></div></section>
    <section class="panel propagation"><h2>日地传播 <small>{{propagationView==='3d'?'三维参数视景':'NOAA 机构模型'}}</small></h2><div class="propagation-tabs"><button :class="{active:propagationView==='3d'}" @click="propagationView='3d'">三维日地场景</button><button :class="{active:propagationView==='2d'}" @click="propagationView='2d'">官方二维模型</button><span>两个视图分别保留数据依据</span></div><SolarPropagation3D v-if="propagationView==='3d'" :time="clock" :events="data?.events||[]" :simulations="data?.simulations||[]" :training-active="trainingActive" :wind="{speed:latestPoint('speed')?.v,density:latestPoint('density')?.v,bz:latestPoint('bz')&&latestPoint('speed')&&Math.abs(latestPoint('bz')!.t-latestPoint('speed')!.t)<=300?latestPoint('bz')!.v:undefined,observedAt:latestPoint('speed')&&latestPoint('density')&&Math.abs(latestPoint('speed')!.t-latestPoint('density')!.t)<=300?Math.min(latestPoint('speed')!.t,latestPoint('density')!.t):undefined}" :selected-id="selected?.activityID" @time="pickTime" @select="id=>selected=data?.events.find(e=>e.activityID===id)||null"/><div v-show="propagationView==='2d'" class="official-model-view"><div class="run-controls"><label>运行批次 <select v-model="run"><option value="">暂无运行</option><option v-for="r in runs" :key="r.run" :value="r.run">{{r.run}} · {{r.frames}}帧</option></select></label><button :disabled="!run" @click="pin">固定批次</button><button @click="full">全屏</button></div><div class="model-image"><img v-if="current" :key="current.id" :src="asset(current.id)" alt="NOAA WSA–ENLIL 密度、速度分布与预测曲线" @load="imageFailed=false;frameReady=true" @error="imageFailed=true;playing=false"/><div v-else class="empty">等待官方模型清单<br/>当前没有传播帧，未生成替代动画</div><p v-if="imageFailed" class="notice">此帧未缓存或获取失败 <button @click="loadFrames">重试</button></p></div><div class="playback"><button :disabled="!frames.length" @click="playing=!playing">{{playing?'暂停':'播放'}}</button><button @click="step(-1)">上一帧</button><input type="range" :min="0" :max="Math.max(0,frames.length-1)" :value="index" aria-label="传播帧时间轴" @input="index=Number(($event.target as HTMLInputElement).value)"/><button @click="step(1)">下一帧</button><select v-model.number="speed"><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></div><p>模型有效时刻：<strong>{{fmt(current?.valid)}}</strong> · {{index+1}}/{{frames.length}}帧</p><p>运行时间与模式见官方原图；背景太阳风不代表已发生 CME。</p><label class="comparison-select">比较批次 <select v-model="compareRun"><option value="">关闭对照</option><option v-for="r in runs.filter(r=>r.run!==run)" :key="r.run" :value="r.run">{{r.run}}</option></select></label><img v-if="comparison" class="compare-image" :src="asset(comparison.id)" alt="同一有效时刻的另一运行批次"/><p v-else-if="compareRun">此批次没有对应时刻的帧，不使用邻近帧冒充。</p><a href="https://www.spaceweather.gov/products/wsa-enlil-solar-wind-prediction" target="_blank" rel="noreferrer">官方产品说明 ↗</a></div></section>
    <aside class="right-panels"><section class="panel"><h2>地球日照范围 <small>随选中时刻变化</small></h2><DaylightMap :time="cursor||clock"/></section><section class="panel"><h2>权威通报 <small>NOAA · 保留原文</small><button @click="showAlerts=!showAlerts">{{showAlerts?'收起':'展开'}}</button></h2><p>通报列表包含历史与续报，不直接视为当前全部有效。</p><label class="alert-filter"><input v-model="communicationOnly" type="checkbox"/>仅显示短波通信相关通报</label><div class="alerts"><details v-for="a in shownAlerts.slice(0,showAlerts?100:5)" :key="a.issue_datetime+a.product_id"><summary>{{a.title||a.product_id}} · {{a.product_id}} · {{fmt(a.issue_datetime+'Z')}} · {{({valid:'有效期内',expired:'有效期已过',cancelled:'取消通报',upcoming:'尚未生效',unknown:'有效期未明确'} as Record<string,string>)[a.status]||'有效期待核验'}}</summary><p v-if="a.valid_until">有效至 {{fmt(a.valid_until)}}</p><pre>{{a.message}}</pre></details><p v-if="!data?.alerts.length">暂无已留存通报，不能据此判定无风险。</p></div></section><section class="panel forecast"><h2>未来三天机构预报 <small>NOAA SWPC</small></h2><div v-if="data?.forecast?.days?.length" class="forecast-table"><p>发布 {{fmt(data.forecast.issued_at)}} · 有效至 {{fmt(data.forecast.valid_until)}}</p><p v-if="data.forecast.issued_at&&clock-Date.parse(data.forecast.issued_at)/1000>64800" class="notice">预报发布时间超过18小时，请核对更新</p><table><thead><tr><th>日期 UTC</th><th>最大Kp</th><th>R1–R2</th><th>≥R3</th><th>≥S1</th></tr></thead><tbody><tr v-for="d in data.forecast.days" :key="d.date"><td>{{d.date}}</td><td>{{d.kp_max??'—'}}</td><td>{{d.r1_r2??'—'}}%</td><td>{{d.r3_plus??'—'}}%</td><td>{{d.s1_plus??'—'}}%</td></tr></tbody></table></div><p>R：无线电中断等级；S：粒子辐射等级；Kp：地磁活动指数。机构概率不等于具体设备故障概率。</p><details><summary>查看机构原文</summary><pre>{{data?.forecast?.text||'等待机构预报。没有资料时不填充示例数字。'}}</pre></details><a href="https://www.spaceweather.gov/products/3-day-forecast" target="_blank" rel="noreferrer">机构原文 ↗</a></section></aside>
  </div>
  <div class="charts-grid"><section v-for="[metric,title] in [['xray','GOES X射线 · 0.1–0.8nm'],['speed','L1 太阳风速度'],['bz','IMF Bz · GSM'],['kp','行星 Kp · 观测'],['protons','GOES ≥10MeV 质子通量'],['density','L1 质子密度'],['bt','IMF Bt'],['kp_forecast','Kp · 机构预报'] ]" :key="metric" class="panel"><h2>{{title}} <small>{{metric==='kp_forecast'?'预报与观测来源见原始产品':'观测'}}</small></h2><MonitorChart :points="series[metric!]?.points||[]" :unit="series[metric!]?.unit||''" :logarithmic="metric==='xray'||metric==='protons'" :bars="metric==='kp'||metric==='kp_forecast'" :cursor="cursor" :utc="useUTC" @select="pickTime"/></section></div>
  <div class="events-grid"><details class="panel event-library"><summary>CME 事件与分析 <small>{{data?.events.length||0}} 条 · NASA DONKI</small></summary><input v-model="eventSearch" placeholder="检索事件、源区或NOAA编号" aria-label="检索太阳事件"/><div class="event-list"><button v-for="event in shownEvents" :key="event.activityID" :class="{chosen:selected?.activityID===event.activityID}" @click="selected=event"><time>{{fmt(event.startTime)}}</time><span>{{event.activityID}}</span><span>{{event.sourceLocation||'位置未提供'}}</span></button><p v-if="!data?.events.length">暂无已获取事件</p></div></details><details class="panel event-verification"><summary>事件关联与地球到达核验 <small>{{selected?'已选事件 · 展开查看':'按需展开'}}</small></summary><template v-if="selected"><b>{{selected.activityID}}</b><p>源区 {{selected.sourceLocation||'未知'}} · NOAA {{selected.activeRegionNum||'未提供'}}</p><p>{{selected.note}}</p><p class="impact-state"><b>{{selectedImpact.title}}</b> · {{selectedImpact.detail}}</p><p>地球到达：{{fmt(selectedImpact.arrival)}} · 命中概率：来源未给出量化值</p><details v-if="selectedSimulations.length"><summary>核对全部关联运行（包含历史修订）</summary><div v-for="s in selectedSimulations" :key="s.simulationID||s.link||s.modelCompletionTime||'unknown'" class="arrival"><b>{{arrival(s)}}</b><span>研究模拟 {{s.simulationID||'来源内嵌运行'}} · 完成 {{fmt(s.modelCompletionTime)}}</span><a v-if="s.link" :href="s.link" target="_blank" rel="noreferrer">原始分析 ↗</a></div></details><p v-if="!selectedSimulations.length">未取得明确关联的传播模拟；不按同日发生自动关联。</p><p>预计时刻经过不自动认定已经到达。</p></template><p v-else>选择事件查看来源提供的关联。NOAA 传播图与 DONKI 研究模拟分别标识。</p></details></div>
  <footer>观测事实 / NOAA 机构预报 / NASA 研究模拟 · 所有资料均保留来源与时间 · 公开信息辅助参考，不代表具体通信链路故障预测</footer>
  <div v-if="imageOpen" class="image-modal" @click="imageOpen=null"><button>关闭</button><img :src="asset(imageOpen.id)" :alt="imageOpen.instrument"/><p>{{imageOpen.time_note}}</p></div>
</div>
</template>
